<script setup lang="ts">
import {computed,onMounted,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';
const {recorder}=useApplication(),route=useRoute(),router=useRouter();const visible=computed(()=>route.name!=='recording'&&!!recorder.record.value&&!recorder.record.value.finished&&(recorder.record.value.parts.length>0||['RECORDING','PAUSED','SAVING'].includes(recorder.phase.value)));
const clock=computed(()=>{const t=Math.floor(recorder.elapsed.value/1000);return `${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;});let timer:ReturnType<typeof setInterval>|null=null;
function beforeUnload(event:BeforeUnloadEvent){if(['RECORDING','PAUSED','SAVING','AUTHORIZING','ERROR'].includes(recorder.phase.value)&&recorder.record.value?.parts.some(p=>['RECORDING','PAUSED','SAVING'].includes(p.state))){event.preventDefault();event.returnValue='';}}
onMounted(()=>{timer=setInterval(recorder.tick,250);window.addEventListener('beforeunload',beforeUnload);});onUnmounted(()=>{if(timer)clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template><button v-if="visible" class="acr-floating-recording" :class="{'is-paused':recorder.phase.value!=='RECORDING','is-saving':recorder.phase.value==='SAVING','has-error':recorder.phase.value==='ERROR'}" aria-label="返回在线录音" :title="'在线录音 · '+clock" @click="router.push('/recording/'+recorder.record.value!.meeting)"><span class="acr-floating-ring"></span><Icon name="mic" :size="24"/><span class="acr-floating-state">{{recorder.phase.value==='RECORDING'?'●':recorder.phase.value==='ERROR'?'!':'Ⅱ'}}</span><span class="acr-floating-tip">在线录音 · {{clock}}</span></button></template>
